const photoUrls=new Map(),photoPending=new Set();
async function hydratePhotos(){
 for(const img of $$('img[data-patient-photo]',root)){
  const pid=img.dataset.patientPhoto,asset=img.dataset.photoAsset||'',id=pid+'/'+asset;
  if(photoUrls.has(id)){img.src=photoUrls.get(id);continue}
  if(photoPending.has(id))continue;
  photoPending.add(id);
  try{const r=await fetch('/api/photos/'+encodeURIComponent(pid)+(asset?'/'+encodeURIComponent(asset):''),{cache:'no-store'});if(!r.ok)continue;photoUrls.set(id,URL.createObjectURL(await r.blob()));for(const el of $$('img[data-patient-photo]',root))if(el.dataset.patientPhoto+'/'+(el.dataset.photoAsset||'')===id)el.src=photoUrls.get(id)}catch{}finally{photoPending.delete(id)}
 }
}
